begin;
select plan(30);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.set_fixture_connection('00000000-0000-4000-8000-000000000101','drive','connected','fixture:assets')$$,'owner saves read-only fixture folder');
select throws_ok($$select public.set_fixture_connection('00000000-0000-4000-8000-000000000101','drive','connected','real-folder')$$,'23514',null,'real Drive IDs blocked');
select is((select count(*) from public.workspace_connections),1::bigint,'fixture connection persisted');
select lives_ok($$select public.enqueue_onboarding_job('00000000-0000-4000-8000-000000000101','drive.sync')$$,'fixture sync queued');
select is(public.enqueue_onboarding_job('00000000-0000-4000-8000-000000000101','drive.sync'),(select id from public.job_runs where kind='drive.sync'),'sync replay returns same durable job');
select public.claim_job('00000000-0000-4000-8000-000000000101');
select throws_ok($$select public.finish_onboarding_job((select id from public.job_runs where kind='drive.sync'),null,'{"synthetic":true}')$$,'40001',null,'null lease cannot complete job');
reset role;
-- SQL metadata fixture; browser tests upload real raster bytes separately.
insert into storage.objects(bucket_id,name) values('brand-assets','00000000-0000-4000-8000-000000000101/'||repeat('a',64)||'.png');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select lives_ok($$select public.record_asset_upload('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000101/'||repeat('a',64)||'.png','synthetic-logo.png',repeat('a',64),'image/png',100,'upload')$$,'verified server asset record persisted');
select lives_ok($$select public.record_asset_upload('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000101/'||repeat('a',64)||'.png','alias.png',repeat('a',64),'image/png',100,'zip')$$,'content hash replay deduplicated');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.assets),1::bigint,'one asset after retry');
select is((select count(*) from storage.objects where bucket_id='brand-assets'),1::bigint,'owner sees private object');
select public.begin_asset_import('00000000-0000-4000-8000-000000000101',repeat('b',64),'zip');
select lives_ok($$select public.record_import_item('00000000-0000-4000-8000-000000000101',(select id from public.asset_imports),'logo.png','stored',(select id from public.assets))$$,'per-file successful import outcome stored');
select lives_ok($$select public.record_import_item('00000000-0000-4000-8000-000000000101',(select id from public.asset_imports),'hostile.svg','failed',null,'invalid_file')$$,'per-file failure stored');
select public.complete_asset_import('00000000-0000-4000-8000-000000000101',(select id from public.asset_imports));
select is((select state from public.asset_imports),'partial','partial import remains visible');
select public.enqueue_onboarding_job('00000000-0000-4000-8000-000000000101','assets.classify');
select public.claim_job('00000000-0000-4000-8000-000000000101');
select throws_ok($$select public.record_asset_upload('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000001','x','x',repeat('a',64),'image/png',100,'upload')$$,'42501',null,'client cannot bypass binary verification');
select lives_ok($$select public.correct_asset('00000000-0000-4000-8000-000000000101',(select id from public.assets),1,'logo')$$,'owner correction persists');
select throws_ok($$select public.correct_asset('00000000-0000-4000-8000-000000000101',(select id from public.assets),1,'product')$$,'40001',null,'stale correction denied');
select is((select classification_source from public.assets),'owner','owner tags retained');
select lives_ok($$select public.finish_onboarding_job((select id from public.job_runs where kind='assets.classify'),(select lease_token from public.job_runs where kind='assets.classify'),jsonb_build_object('synthetic',true,'assets',jsonb_build_array(jsonb_build_object('id',(select id from public.assets),'category','unusable','confidence',0))))$$,'stale fixture classification skips manual correction');
select is((select category from public.assets),'logo','late classification cannot replace owner tags');
select public.enqueue_onboarding_job('00000000-0000-4000-8000-000000000101','brand.extract','{"sourceText":"#112233; font: Inter"}');
select public.claim_job('00000000-0000-4000-8000-000000000101');
select lives_ok($$select public.finish_onboarding_job((select id from public.job_runs where kind='brand.extract'),(select lease_token from public.job_runs where kind='brand.extract'),'{"synthetic":true,"colors":["#112233"],"fonts":["Inter"]}')$$,'structured brand kit extraction persists');
select lives_ok($$select public.approve_brand_kit('00000000-0000-4000-8000-000000000101',1)$$,'owner approves current extracted kit');
select throws_ok($$select public.approve_brand_kit('00000000-0000-4000-8000-000000000101',2)$$,'40001',null,'stale kit approval denied');

select lives_ok($$select public.save_brand('00000000-0000-4000-8000-000000000101',1,'Original demo brand','cedar-lane.example','Corrected fictional facts','Plain voice','No invented offers')$$,'owner brand correction stored');
select is((select count(*) from public.brand_versions),2::bigint,'brand version history retained');
select is((select calendar_state from public.campaigns limit 1),'proposed','brand correction invalidates dependent calendar');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select throws_ok($$select public.set_fixture_connection('00000000-0000-4000-8000-000000000101','klaviyo','connected')$$,'42501',null,'staff cannot connect fixture account');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.assets),0::bigint,'other tenant cannot enumerate assets');
select is((select count(*) from storage.objects where bucket_id='brand-assets'),0::bigint,'other tenant cannot enumerate private Storage');
select is((select count(*) from public.brand_versions),1::bigint,'other tenant sees only own brand history');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.assets),0::bigint,'designer cannot enumerate unrelated brand assets');
select * from finish();
rollback;
